action.command:
cd /tmp && rm -f cj.txt && TOKEN=$(curl -s -c cj.txt -m 20 http://127.0.0.1:3000/ | grep -o 'name="csrf-token" content="[^"]*"' | head -1 | sed 's/.*content="//;s/"//'); curl -s -b cj.txt -c cj.txt -m 30 -X POST http://127.0.0.1:3000/api/v1/signin -H 'Content-Type: application/json' -H "X-CSRF-Token: $TOKEN" -d '{"username":"admin@example.com","password":"test","fingerprint":"test-device-12345"}' -w "
HTTP %{http_code}
" -o /tmp/signin2.json; echo "---BODY---"; head -c 600 /tmp/signin2.json; echo; echo "---ME---"; curl -s -b cj.txt -m 20 "http://127.0.0.1:3000/api/v1/users/me?fingerprint=test-device-12345" -w "
HTTP %{http_code}
" | head -c 600
